<script setup>
import {ref,onMounted} from 'vue';
import api from '../../services/api';
const emit=defineEmits(['state']);
const state=ref(null),choices=ref([]),confirmed=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const labels={billing:'Billing — assigned balances, payments and receipts',insurance:'Insurance — policies and insurance cards',contact:'Contact details — view and request updates',scheduling:'Scheduling — upcoming appointments and change requests'};
const presets={none:[],billing:['billing'],billing_insurance:['billing','insurance'],administrative:['billing','insurance','contact','scheduling']};
const presetFor=c=>c.custom?'custom':Object.keys(presets).find(k=>[...presets[k]].sort().join() === [...c.scopes].sort().join())||'custom';
function setPreset(c,key){c.custom=key==='custom';if(!c.custom)c.scopes=[...presets[key]];confirmed.value=false;}
async function load(){busy.value=true;error.value='';try{state.value=(await api.get('/dependent-portal/independence')).data;choices.value=state.value.helpers.flatMap(p=>state.value.agencies.map(a=>({helperUserId:p.id,agencyId:a.id,name:p.name,agencyName:a.name,scopes:[...(state.value.choices.find(c=>Number(c.helperUserId)===Number(p.id)&&Number(c.agencyId)===Number(a.id))?.scopes||[])]})));confirmed.value=false;emit('state',state.value);}catch(e){state.value=null;error.value=e.response?.data?.error?.message||'Access settings could not be loaded.';}finally{busy.value=false;}}
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const payload={version:state.value.version,confirmed:confirmed.value,choices:choices.value.map(({helperUserId,agencyId,scopes})=>({helperUserId,agencyId,scopes}))};if(state.value.status==='active')await api.put('/dependent-portal/independence/assistance',payload);else await api.post('/dependent-portal/independence/request',payload);notice.value=state.value.status==='active'?'Your assistance permissions are updated.':'Your request is with the team for an authority review. Existing access has not changed yet.';await load();}catch(e){error.value=e.response?.data?.error?.message||'Your choices could not be saved.';}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="access-choices"><h2>Access &amp; independence</h2><p>You keep your own login, appointments and private conversations. Choose who may help with the rest, separately for each agency.</p><p v-if="busy&&!state" role="status">Loading access settings…</p><p v-if="error" role="alert">{{error}} <button @click="load">Refresh</button></p><p v-if="notice" role="status">{{notice}}</p><form v-if="state" @submit.prevent="save">
<p class="status">{{state.status==='active'?'You control your account.':'Your team must review identity and legal authority before family access changes.'}} <span v-if="state.status==='requested'">Review requested.</span><span v-if="state.status==='declined'">Please contact your team about the previous review.</span></p>
<p v-if="state.ageReviewRequired&&state.status!=='active'">If you are under 18, legal authority and any service-specific privacy rights need individual review.</p>
<fieldset v-for="c in choices" :key="`${c.helperUserId}:${c.agencyId}`"><legend>{{c.name}} · {{c.agencyName}}</legend><label>Access level<select :value="presetFor(c)" @change="setPreset(c,$event.target.value)"><option value="none">No access — fully disconnected</option><option value="billing">Billing only</option><option value="billing_insurance">Billing + insurance</option><option value="administrative">Administrative help</option><option value="custom">Custom permissions</option></select></label><label v-for="(label,key) in labels" :key="key" class="choice"><input v-model="c.scopes" type="checkbox" :value="key" @change="confirmed=false" />{{label}}</label></fieldset>
<p v-if="!choices.length">No other people are currently linked to this account.</p>
<details><summary>What these permissions mean</summary><ul><li>These options never give someone your password, private messages or clinical records. Clinical sharing needs its own authorization and review.</li><li>Billing permission does not sign a payment authorization. The payer must accept their own responsibility and recurring-payment terms.</li><li>Removing billing permission stops future automatic charges for that person. Existing balances and their receipts remain; billing coordinates any payment already in progress.</li><li>Contact and scheduling help lets someone request changes from the office. It does not let them reset your login or join a private session.</li><li>Insurance statements may still reach the policyholder. Ask your team and insurer about confidential communications.</li></ul></details>
<label class="choice confirm"><input v-model="confirmed" type="checkbox" required />These are my choices. I understand that independence removes the former family access and keeps only the assistance selected here.</label><button :disabled="busy||!confirmed">{{busy?'Saving…':state.status==='active'?'Confirm my access choices':'Request independence review'}}</button></form></section></template>
<style scoped>.access-choices{background:white;padding:24px;border:1px solid #d5e1eb;border-radius:16px;color:#193653}.access-choices p,.access-choices li{line-height:1.6}.access-choices fieldset{border:1px solid #bfd1df;border-radius:12px;margin:20px 0;padding:18px}.access-choices legend{font-weight:700;padding:0 6px}.access-choices label{display:grid;gap:8px}.access-choices .choice{display:flex;gap:10px;align-items:flex-start;margin:16px 0}.choice input{margin-top:5px;flex-shrink:0;width:18px;height:18px}.access-choices select{font:inherit;padding:10px;border:1px solid #adc3d4;border-radius:8px;width:100%;background:white;color:#193653}.access-choices button{padding:12px 18px;font:inherit;border:0;border-radius:8px;background:#245f92;color:white;cursor:pointer}.access-choices button:disabled{opacity:.6}.access-choices ul{padding-left:24px}.status{padding:12px;background:#eef5fb;border-radius:10px}[role=alert]{color:#a12424}.confirm{padding-top:16px;border-top:1px solid #d5e1eb}</style>
